module uart_tx_ai(
	Clk,
	Reset_n,
	Tx_Go,
	data,
	num_of_ai,
	uart_tx,
	Trans_Done);

	//---Ports declearation: generated by Robei---
	input Clk;
	input Reset_n;
	input Tx_Go;
	input [7:0] data;
	input [7:0] num_of_ai;
	output uart_tx;
	output Trans_Done;

	wire Clk;
	wire Reset_n;
	wire Tx_Go;
	wire [7:0] data;
	wire [7:0] num_of_ai;
	wire uart_tx;
	reg Trans_Done;

	//----Code starts here: integrated by Robei-----
	    //Trans_Done的作用是增加代码的可构性，发送完指令后，对Trans_Done拉高，这个接口主要用来给做扩展设计的。
	    
	   
	    wire Tx_done;
	    wire Trans_Go;
	    reg [7:0]Data;
	    reg Send_Go;
	    reg [71:0]Data72;
		reg test_en_dly1;
		reg test_en_dly2;
		
		
		//按键信号打拍
		always@(posedge Clk)
		begin
			test_en_dly1 <= Tx_Go;
			test_en_dly2 <= test_en_dly1;
		end
	
	  //控制发送使能
		assign Trans_Go = test_en_dly1 & !test_en_dly2;
	
	   //需要发送的指令字符，读取血氧的指令为AT+SPO2\r\n
	   //需要增加字符的，可以增加Data的位宽
		always@(*)
	    begin
	//		 Data72 <= "n\r\2OPS+TA";    
			 Data72[7:0]    <= 8'hAA;
			 Data72[15:8]  <= 8'h55;
			 Data72[23:16]<= num_of_ai;
			 Data72[31:24]<= data;
			 Data72[39:32]<= 8'h00;
			 Data72[47:40]<= 8'h00;
			 Data72[55:48]<= 8'h00;
			 Data72[63:56]<= 8'h55;
			 Data72[71:64]<= 8'hAA;		 
		end
	    
	    
		//通过状态机的方式，将数据发送出去，每次发8位，总共9个数据
	    reg [3:0]state;
	    always@(posedge Clk or negedge Reset_n)
	    if(!Reset_n)begin
	        state <= 0;
	        Data <= 0;
	        Send_Go <= 0; 
	        Trans_Done <= 0;
	    end
	    else begin
	        case(state)
	            0:
	            begin
	                Trans_Done <= 0;
	                if(Trans_Go)begin
	                    Data <= Data72[7:0];
	                    Send_Go <= 1; 
	                    state <= 1;     
	                end
	                else begin
	                    Data <= Data;
	                    Send_Go <= 0; 
	                    state <= 0;         
	                end
	           end
	               
	           1:
	            begin
	                if(Tx_done)begin
	                    Data <= Data72[15:8];
	                    Send_Go <= 1;
	                    state <= 2;
	                end
	                else begin
	                    Data <= Data;
	                    Send_Go <= 0;
	                    state <= 1;
	                end
	            end
	            
	            2:
	            begin
	                if(Tx_done)begin
	                    Data <= Data72[23:16];
	                    Send_Go <= 1;
	                    state <= 3;
	                end
	                else begin
	                    Data <= Data;
	                    Send_Go <= 0;
	                    state <= 2;
	                end
	            end 
	              
	            3:
	            begin
	                if(Tx_done)begin
	                    Data <= Data72[31:24];
	                    Send_Go <= 1;
	                    state <= 4;
	                end
	                else begin
	                    Data <= Data;
	                    Send_Go <= 0;
	                    state <= 3;
	                end
	            end  
	                   
	            4:
	            begin
	                if(Tx_done)begin
	                    Data <= Data72[39:32];
	                    Send_Go <= 1;
	                    state <= 5;
	                end
	                else begin
	                    Data <= Data;
	                    Send_Go <= 0;
	                    state <= 4;
	                end
	            end  
	            
	            5:
	            begin
	                if(Tx_done)begin
	                    Data <= Data72[47:40];
	                    Send_Go <= 1;
	                    state <= 6;
	                end
	                else begin
	                    Data <= Data;
	                    Send_Go <= 0;
	                    state <= 5;
	                end
	            end              
	            
	            6:
	            begin
	                if(Tx_done)begin
	                    Data <= Data72[55:48];
	                    Send_Go <= 1;
	                    state <= 7;
	                end
	                else begin
	                    Data <= Data;
	                    Send_Go <= 0;
	                    state <= 6;
	                end
	            end             
	            
	            7:
	            begin
	                if(Tx_done)begin
	                    Data <= Data72[63:56];
	                    Send_Go <= 1;
	                    state <= 8;
	                end
	                else begin
	                    Data <= Data;
	                    Send_Go <= 0;
	                    state <= 7;
	                end
	            end           
	
	            8:
	            begin
	                if(Tx_done)begin
	                    Data <= Data72[71:64];
	                    Send_Go <= 1;
	                    state <= 9;
	                end
	                else begin
	                    Data <= Data;
	                    Send_Go <= 0;
	                    state <= 8;
	                end
	            end     
	                                
	            9:
	            begin
	                if(Tx_done)begin
	                    Send_Go <= 0;
	                    Trans_Done <= 1;
	                    state <= 0;
	                end
	                else begin
	                    Data <= Data;
	                    Send_Go <= 0;
	                    state <= 9;
	                end
	            end 
	            default:   
	                begin
	                    Data <= Data;
	                    Send_Go <= 0;
	                    state <= 0;
	                end
	        endcase
	    end
	//---Module instantiation---
	uart_byte_tx uart_byte_tx1(
		.Clk(Clk),
		.Reset_n(Reset_n),
		.Data(Data),
		.Send_Go(Send_Go),
		.Baud_set(3'd5),
		.uart_tx(uart_tx),
		.Tx_done(Tx_done));

endmodule    //uart_tx_ai

